mapper.select:
SELECT owner_user_id, payee_user_id, alias, success_count, last_success_at,
       pinned, hidden, version, created_at, updated_at
FROM contact
WHERE owner_user_id = #{ownerUserId}
  AND payee_user_id = #{payeeUserId}

mapper.update:
UPDATE contact
SET alias = #{alias},
    pinned = #{pinned},
    hidden = #{hidden},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE owner_user_id = #{ownerUserId}
  AND payee_user_id = #{payeeUserId}
  AND version = #{version}
